-- LOCAL ONLY. New auth/profile operations, all fixtures rolled back.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select ok(not (select rolcanlogin or rolbypassrls or rolsuper or rolcreaterole from pg_roles where rolname='vila_rica_staff_writer'),'Writer cannot login or bypass RLS');
select ok(not pg_has_role('authenticated','vila_rica_staff_writer','MEMBER'),'Authenticated cannot assume writer');
select ok(not pg_has_role('anon','vila_rica_staff_writer','MEMBER'),'Anon cannot assume writer');
select ok(not pg_has_role('service_role','vila_rica_staff_writer','MEMBER'),'Service role cannot assume writer');
select ok(not (select rolinherit from pg_roles where rolname='vila_rica_staff_writer'),'Writer does not inherit privileges');
select ok(not has_table_privilege('vila_rica_staff_writer','public.orders','INSERT,UPDATE,DELETE'),'Writer cannot mutate orders');
select ok(not has_table_privilege('vila_rica_staff_writer','public.products','INSERT,UPDATE,DELETE'),'Writer cannot mutate products');
select ok(not has_table_privilege('vila_rica_staff_writer','public.payment_events','INSERT,UPDATE,DELETE'),'Writer cannot mutate payments');
select ok(not has_table_privilege('authenticated','public.profiles','UPDATE,INSERT,DELETE'),'No generic profile mutations');
select ok(not has_table_privilege('authenticated','private.staff_access_audit','SELECT,INSERT,UPDATE,DELETE'),'Audit not exposed to clients');
select ok(not has_function_privilege('authenticated','private.bootstrap_staff_admin(uuid,text)','EXECUTE'),'Bootstrap not exposed');
select ok(not has_function_privilege('authenticated','private.write_staff_profile(uuid,uuid,text,text,boolean,boolean)','EXECUTE'),'Internal writer not exposed');
select ok(not has_function_privilege('anon','public.manage_staff_profile(uuid,text,text,boolean)','EXECUTE'),'Anonymous management denied');
select ok(not has_function_privilege('service_role','public.manage_staff_profile(uuid,text,text,boolean)','EXECUTE'),'Service key cannot perform management');
select is((select count(*)::integer from public.profiles),0,'Migration creates no profiles');
insert into auth.users(id) values
 ('63000000-0000-4000-8000-000000000001'),('63000000-0000-4000-8000-000000000002'),
 ('63000000-0000-4000-8000-000000000003'),('63000000-0000-4000-8000-000000000004');
select lives_ok($$select private.bootstrap_staff_admin('63000000-0000-4000-8000-000000000001','Primeiro admin teste')$$,'Owner-only bootstrap succeeds for existing identity');
select throws_ok($$select private.bootstrap_staff_admin('63000000-0000-4000-8000-000000000002','Outro admin teste')$$,'42501','Bootstrap already completed','Bootstrap cannot run twice');
grant usage on schema extensions to authenticated;
grant execute on all functions in schema extensions to authenticated;
set local role authenticated;
set local request.jwt.claim.sub='63000000-0000-4000-8000-000000000001';
select lives_ok($$select public.manage_staff_profile('63000000-0000-4000-8000-000000000002','Atendente teste','atendente',true)$$,'Admin links existing Auth identity');
select throws_ok($$select public.manage_staff_profile('63000000-0000-4000-8000-000000000001','Meu perfil','admin',false)$$,'42501','Self changes forbidden','Admin cannot disable own profile');
select throws_ok($$select public.manage_staff_profile('63000000-0000-4000-8000-999999999999','Inexistente teste','admin',true)$$,'22023','Existing Auth identity required','No imaginary Auth identities');
select throws_ok($$select public.manage_staff_profile('63000000-0000-4000-8000-000000000003','Papel inválido','root',true)$$,'22023','Invalid profile input','Unknown role rejected');
set local request.jwt.claim.sub='63000000-0000-4000-8000-000000000002';
select throws_ok($$select public.manage_staff_profile('63000000-0000-4000-8000-000000000002','Autopromoção','admin',true)$$,'42501','Active administrator required','Attendant cannot self promote');
select throws_ok($$select public.manage_staff_profile('63000000-0000-4000-8000-000000000003','Outro teste','atendente',true)$$,'42501','Active administrator required','Attendant cannot change colleagues');
set local request.jwt.claim.sub='63000000-0000-4000-8000-000000000004';
select throws_ok($$select public.manage_staff_profile('63000000-0000-4000-8000-000000000002','Sem perfil','admin',true)$$,'42501','Active administrator required','Auth identity without profile denied');
set local request.jwt.claim.sub='63000000-0000-4000-8000-000000000001';
select lives_ok($$select public.manage_staff_profile('63000000-0000-4000-8000-000000000002','Admin secundário','admin',true)$$,'Admin promotion controlled by existing active admin');
select lives_ok($$select public.manage_staff_profile('63000000-0000-4000-8000-000000000003','Inativo teste','admin',false)$$,'Admin can link inactive profile');
set local request.jwt.claim.sub='63000000-0000-4000-8000-000000000003';
select throws_ok($$select public.manage_staff_profile('63000000-0000-4000-8000-000000000001','Admin alvo','admin',false)$$,'42501','Active administrator required','Inactive admin denied');
set local request.jwt.claim.sub='63000000-0000-4000-8000-000000000001';
select lives_ok($$select public.manage_staff_profile('63000000-0000-4000-8000-000000000002','Admin desativado','admin',false)$$,'Other admin can be deactivated while actor remains active');
select throws_ok($$update public.profiles set role='admin'$$,'42501',null,'Direct update still denied');
select throws_ok($$update public.orders set status='concluido'$$,'42501',null,'Commercial writes still denied');
reset role;
select is((select count(*)::integer from public.profiles where role='admin' and active),1,'At least one active admin survives');
select is((select count(*)::integer from private.staff_access_audit),5,'All successful sensitive changes audited, failures roll back');
select throws_ok($$update private.staff_access_audit set operation='bootstrap'$$,'42501','Backend foundation is read-only until transactional operations are approved','Audit immutable');
select throws_ok($$insert into public.profiles(id,full_name,role,active) values('63000000-0000-4000-8000-000000000004','Owner direto','admin',true)$$,'42501','Backend foundation is read-only until transactional operations are approved','Owner generic profile insert still blocked');
select * from finish();
rollback;
